<?php $total = customer_query($filters, true); $rows = customer_query($filters); $perPage = max(1, (int) ($filters['per_page'] ?? 10)); $pages = max(1, (int) ceil($total / $perPage)); $start = $total ? (($filters['page'] - 1) * $perPage) + 1 : 0; $end = min($filters['page'] * $perPage, $total); $kpis = customer_kpis(); $kpiIcons = ['Total Customers' => '◎', 'Active Customers' => '✓', 'New Customers' => '+', 'Inactive Customers' => '×']; ?>
<div class="customer-heading"><div><div class="breadcrumb-line">Home <span>›</span> Customers <span>›</span> All Customers</div><h1>All Customers</h1></div><a href="index.php?page=admin&amp;section=customers-add" class="btn btn-primary customer-add-button">＋ Add Customer</a></div>
<div class="row g-3 admin-kpi-row customer-kpis"><?php foreach ($kpis as $label => $value): ?><div class="col-sm-6 col-xl-3"><div class="admin-kpi customer-kpi customer-kpi-<?= e(strtolower(str_replace(' ', '-', $label))) ?>"><span class="kpi-icon"><?= e($kpiIcons[$label]) ?></span><div><span><?= e($label) ?></span><strong><?= number_format($value) ?></strong><small><?= $label === 'Total Customers' ? 'All Time' : ($label === 'New Customers' ? 'This Month' : number_format($total ? ($value / $total) * 100 : 0, 1) . '% of Total') ?></small></div></div></div><?php endforeach; ?></div>
<div class="admin-panel customer-filters-panel"><form class="customer-filter-bar" method="get"><input type="hidden" name="page" value="admin"><input type="hidden" name="section" value="customers"><label>Search<input class="form-control" name="search" value="<?= e($filters['search']) ?>" placeholder="Search by name, phone, email..."></label><label>Status<select class="form-select" name="status"><option value="">All</option><option value="active" <?= $filters['status'] === 'active' ? 'selected' : '' ?>>Active</option><option value="inactive" <?= $filters['status'] === 'inactive' ? 'selected' : '' ?>>Inactive</option></select></label><label>Customer Type<select class="form-select" name="type"><option value="">All</option><option value="individual" <?= $filters['type'] === 'individual' ? 'selected' : '' ?>>Individual</option><option value="company" <?= $filters['type'] === 'company' ? 'selected' : '' ?>>Company</option><option value="walk_in" <?= $filters['type'] === 'walk_in' ? 'selected' : '' ?>>Walk-in</option></select></label><label>From Date<input class="form-control" type="date" name="from" value="<?= e($filters['from']) ?>"></label><label>To Date<input class="form-control" type="date" name="to" value="<?= e($filters['to']) ?>"></label><a class="btn btn-light filter-reset" href="index.php?page=admin&amp;section=customers">↻ Reset</a></form></div>
<div class="admin-panel customer-list-panel"><div class="customer-list-heading"><h2>Customers List</h2><a href="index.php?page=admin&amp;section=customers-export&amp;<?= e(customer_query_string($filters)) ?>" class="btn btn-outline-primary">⇩ &nbsp;Export</a></div><div class="table-responsive"><table class="table admin-table customer-table"><thead><tr><th>#</th><th>Customer Name</th><th>Contact Number</th><th>Email</th><th>Customer Type</th><th>Total Vehicles</th><th>Total Invoices</th><th>Total Due (Rs.)</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if (!$rows): ?><tr><td colspan="10" class="empty-table">No customers found. Add a customer to begin.</td></tr><?php else: ?><?php foreach ($rows as $index => $row): ?><tr><td><?= $start + $index ?></td><td><div class="customer-name"><span class="customer-avatar"><?= e(strtoupper(substr($row['name'], 0, 1))) ?></span><span><strong><?= e($row['name']) ?></strong><small>ID: <?= e($row['customer_code']) ?></small></span></div></td><td><?= e($row['contact_number']) ?></td><td><?= e($row['email'] ?: '-') ?></td><td><span class="type-badge type-<?= e($row['customer_type']) ?>"><?= e(ucwords(str_replace('_', ' ', $row['customer_type']))) ?></span></td><td>0</td><td>0</td><td>0.00</td><td><span class="status-badge status-<?= e($row['status']) ?>"><?= e(ucfirst($row['status'])) ?></span></td><td><div class="action-links"><a aria-label="View customer" href="index.php?page=admin&amp;section=customers-view&amp;id=<?= (int) $row['id'] ?>">◉</a><a aria-label="Edit customer" href="index.php?page=admin&amp;section=customers-edit&amp;id=<?= (int) $row['id'] ?>">✎</a><form method="post" action="index.php?page=admin&amp;section=customers-deactivate&amp;id=<?= (int) $row['id'] ?>" data-customer-status-form data-customer-name="<?= e($row['name']) ?>" data-customer-status="<?= e($row['status']) ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><button aria-label="Change customer status">♙</button></form></div></td></tr><?php endforeach; ?><?php endif; ?></tbody></table></div><div class="customer-table-footer"><span>Showing <?= $start ?> to <?= $end ?> of <?= $total ?> customers</span><div class="customer-pagination-wrap"><?php if ($pages > 1): ?><nav aria-label="Customer pagination"><ul class="pagination pagination-sm mb-0"><?php $query = customer_query_string($filters); ?><li class="page-item <?= $filters['page'] <= 1 ? 'disabled' : '' ?>"><a class="page-link" href="index.php?page=admin&amp;section=customers&amp;<?= e($query) ?>&amp;p=<?= max(1, $filters['page'] - 1) ?>">‹</a></li><?php for ($number = max(1, $filters['page'] - 2); $number <= min($pages, $filters['page'] + 2); $number++): ?><li class="page-item <?= $number === $filters['page'] ? 'active' : '' ?>"><a class="page-link" href="index.php?page=admin&amp;section=customers&amp;<?= e($query) ?>&amp;p=<?= $number ?>"><?= $number ?></a></li><?php endfor; ?><li class="page-item <?= $filters['page'] >= $pages ? 'disabled' : '' ?>"><a class="page-link" href="index.php?page=admin&amp;section=customers&amp;<?= e($query) ?>&amp;p=<?= min($pages, $filters['page'] + 1) ?>">›</a></li></ul></nav><?php endif; ?><label class="items-per-page">Items per page:<select onchange="var u=new URL(window.location.href);u.searchParams.set('per_page',this.value);u.searchParams.delete('p');window.location.href=u.toString();" name="per_page"><option value="10" <?= $perPage === 10 ? 'selected' : '' ?>>10</option><option value="25" <?= $perPage === 25 ? 'selected' : '' ?>>25</option><option value="50" <?= $perPage === 50 ? 'selected' : '' ?>>50</option></select></label></div></div></div>

